const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || [];
if (!vendors.length) return [{ json: { _no_vendors: true } }];
return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || v.name || '',
    website: (v.website || '').replace(/\/$/, ''),
    apify_token: body.apify_token || '',
    openai_api_key: body.openai_api_key || '',
  }
}));

const vendor = $('Split Vendors').first().json;
const crawl = $input.first().json;
const pages = crawl.pages || [];
const page = pages[0] || {};
const text = String(page.text || page.text_excerpt || '');
const wordCount = text.split(/\s+/).filter(w => w.length > 1).length;
// Quality gate: pricing pages need enough content to be meaningful
const hasPricingSignal = /price|pricing|plan|tier|per month|per year|free|paid|enterprise|starter/i.test(text);
const isUsable = wordCount >= 80 && hasPricingSignal;
return [{
  json: {
    vendor_name: vendor.vendor_name,
    website: vendor.website,
    openai_api_key: vendor.openai_api_key,
    pricing_url: page.url || `${vendor.website}/pricing`,
    page_usable: isUsable,
    visible_text: isUsable ? text.slice(0, 8000) : '',
    word_count: wordCount,
  }
}];

const pageData = $('Validate Pricing Page').first().json;
const llmResult = $input.first().json;

// Parse the LLM JSON output
let parsed = null;
try {
  const raw = llmResult.output_text || llmResult.outputText || '';
  parsed = JSON.parse(raw);
} catch(e) {
  // LLM returned non-JSON — treat as miss
}

if (!parsed) {
  return [{ json: { vendor_name: pageData.vendor_name, website: pageData.website, _has_data: false, _miss_reason: 'llm_parse_failed' } }];
}

// Map LLM output to pricing fields
const tiers = Array.isArray(parsed.tiers) ? parsed.tiers : [];
const pricing = tiers.map(t => [t.name, t.price_monthly ? `$${t.price_monthly}/mo` : t.price_annual ? `$${t.price_annual}/yr` : 'custom'].filter(Boolean).join(': '));
const free_trial = parsed.has_free_tier === true;

return [{
  json: {
    vendor_name: pageData.vendor_name,
    website: pageData.website,
    pricing_url: pageData.pricing_url,
    pricing,
    free_trial,
    pricing_source: 'llm_inferred',
    _has_data: pricing.length > 0,
  }
}];
